'use strict';
// Independently authored practice content. Official format metadata is separate.
const EXAM_TOPICS=['Deutsch am Abend','Kochen am Wochenende','Sport im Park','Arbeit im Team','Reisen mit der Bahn','Wohnen in der Stadt','Lernen im Internet','Einkaufen auf dem Markt','Freunde treffen','Kultur im Alltag','Eine Ausbildung beginnen','Umwelt und Verkehr'];
function formatSkill(skill){return {reading:'Lesen',listening:'Hören',grammar:'Sprachbausteine',writing:'Schreiben',speaking:'Sprechen',preparation:'Vorbereitung'}[skill]||skill;}
function practiceQuestions(profile,module,part){
 const n=part.itemCount||5,offset=(part.teil-1)*3,topics=Array.from({length:Math.max(n,12)},(_,i)=>EXAM_TOPICS[(i+offset)%EXAM_TOPICS.length]);
 const letters=topics.map((_,i)=>String.fromCharCode(65+i));
 const matching=/zuordnen|Überschrift|Anzeigen|Informationen|Sprecher/.test(part.name)&&!['listening','grammar'].includes(module.key);
 const binary=/richtig|ja\/nein/i.test(part.name);
 const questions=[];let content='',transcript='';
 if(matching){content=topics.map((topic,i)=>`${letters[i]} · ${topic}: Unser Angebot findet ${['montags','dienstags','mittwochs','donnerstags','freitags','samstags'][i%6]} um ${9+i%10} Uhr statt. Anmeldung im Lernzentrum. ${i%2?'Für Fortgeschrittene mit Vorkenntnissen.':'Auch ohne Vorkenntnisse möglich.'}`).join('\n\n');for(let i=0;i<n;i++)questions.push({id:'q'+i,prompt:`Welche Information passt? Sie suchen ein Angebot zum Thema „${topics[i]}“.`,options:letters,answer:letters[i],answerSource:'authored'});}
 else if(module.key==='grammar'||/Lückentext|Wortteile|Textlücken/.test(part.name)){
 const gaps=[['Ich interessiere mich ___ einen Deutschkurs.',['für','an','mit'],'für'],['Können Sie mir sagen, ___ der Kurs beginnt?',['wann','wenn','als'],'wann'],['Ich lerne Deutsch, weil ich in Deutschland arbeiten ___.',['möchte','möchten','möchtest'],'möchte'],['Letzte Woche ___ ich einen Kurs besucht.',['habe','bin','hat'],'habe'],['Ich fahre mit ___ Bus zum Kurs.',['dem','den','der'],'dem'],['Der Lehrer, ___ hier unterrichtet, ist freundlich.',['der','den','dem'],'der'],['Ich freue mich ___ den nächsten Unterricht.',['auf','über','bei'],'auf'],['Wenn ich mehr Zeit hätte, ___ ich öfter üben.',['würde','werde','wurde'],'würde'],['Ich habe keine Zeit, ___ gehe ich nicht mit.',['deshalb','obwohl','weil'],'deshalb'],['Es ist wichtig, regelmäßig ___ lernen.',['zu','für','um'],'zu']];
 content='Situation: Sie planen einen Deutschkurs. Ergänzen Sie die Lücken in den folgenden Sätzen.';for(let i=0;i<n;i++){const [prompt,options,answer]=gaps[i%gaps.length];questions.push({id:'q'+i,prompt,options,answer,answerSource:'authored'});}
 }else{
 const details=Array.from({length:Math.max(n,10)},(_,i)=>({title:topics[i%topics.length],time:9+i%10,day:['Montag','Dienstag','Mittwoch','Donnerstag','Freitag'][i%5],price:10+i*3}));
 const introduction=profile.level==='B2'?'Obwohl viele Menschen ihre Freizeit individuell gestalten möchten, wächst zugleich das Interesse an gemeinsamen Aktivitäten. Das Lernzentrum hat deshalb sein Programm überarbeitet: Entscheidend sind nicht nur günstige Preise, sondern auch verlässliche Termine und ein klarer Bezug zum Alltag. Die folgenden Veranstaltungen ergänzen das reguläre Angebot.':profile.level==='B1'?'Das Lernzentrum Elio bietet neue Aktivitäten an. Wer teilnehmen möchte, meldet sich spätestens zwei Tage vorher an. Einige Veranstaltungen finden am Wochenende statt. Hier finden Sie die aktuellen Termine:':'Das Lernzentrum hat neue Kurse. Bitte melden Sie sich vorher an. Hier sind die Termine:';
 content=introduction+'\n\n'+details.map(d=>`„${d.title}“: ${d.day}, ${d.time}:00 Uhr, ${d.price} Euro.`).join('\n');
 if(module.key==='listening'){transcript=details.slice(0,n).map((d,i)=>`Nachricht ${i+1}. Guten Tag! Die Veranstaltung „${d.title}“ findet am ${d.day} statt. Bitte kommen Sie um ${d.time} Uhr. Die Teilnahme kostet ${d.price} Euro. Wir freuen uns auf Sie.`).join('\n\n');content='Hören Sie die Aufnahme und beantworten Sie die Aufgaben. Der Text bleibt bis zur Abgabe verborgen.';}
 for(let i=0;i<n;i++){const d=details[i%details.length];if(binary){const truth=i%2===0;questions.push({id:'q'+i,prompt:`„${d.title}“ beginnt um ${truth?d.time:d.time+1}:00 Uhr.`,options:['Richtig','Falsch'],answer:truth?'Richtig':'Falsch',answerSource:'authored'});}else{const options=[`${d.time}:00`,`${d.time+1}:00`,`${d.time+2}:00`];const rotate=i%3;const rotated=[...options.slice(rotate),...options.slice(0,rotate)];questions.push({id:'q'+i,prompt:`Wann beginnt „${d.title}“?`,options:rotated,answer:options[0],answerSource:'authored'});}}
 }
 return {content,transcript,questions};
}
function speakingPractice(profile,part){const titles={
 'Goethe-A1':['Stellen Sie sich vor. Buchstabieren Sie Ihren Namen und nennen Sie eine Telefonnummer.','Fragen Sie Ihren Partner nach Essen, Freizeit und Wohnen. Antworten Sie auf seine Fragen.','Bitten Sie Ihren Partner um ein Glas Wasser und reagieren Sie auf seine Bitte.'],
 'Goethe-A2':['Fragen Sie Ihren Partner nach Geburtstag, Wohnort und Beruf. Antworten Sie selbst.','Sprechen Sie über Ihren Alltag, Hobbys und Ihr Wochenende.','Planen Sie einen gemeinsamen Einkauf: Wann, wo, was und wie viel?'],
 'Goethe-B1':['Planen Sie gemeinsam einen Kochabend: Termin, Ort, Zutaten, Aufgaben und Kosten.','Präsentieren Sie „Zu Hause oder im Restaurant essen?“. Berichten Sie über Erfahrungen und Ihr Heimatland, nennen Sie Vor-/Nachteile und Ihre Meinung.','Geben Sie Rückmeldung zur Präsentation Ihres Partners über Sport und stellen Sie eine Frage. Beantworten Sie Rückfragen zu Ihrer Präsentation.'],
 'Goethe-B2':['Halten Sie einen kurzen Vortrag zum Thema „Nachhaltig reisen“. Beschreiben Sie mehrere Möglichkeiten, Vor-/Nachteile und eine Möglichkeit genauer. Reagieren Sie auf Fragen.','Diskutieren Sie: Sollten öffentliche Verkehrsmittel kostenlos sein? Tauschen Sie Argumente aus, reagieren Sie aufeinander und fassen Sie Ihre Position zusammen.'],
 'Telc-A1':['Stellen Sie sich vor und buchstabieren Sie Ihren Namen.','Fragen Sie nach Essen, Wohnen und Freizeit. Geben Sie Informationen.','Formulieren Sie Bitten und reagieren Sie auf Bitten Ihres Partners.'],
 'Telc-A2':['Stellen Sie sich vor: Name, Herkunft, Beruf, Wohnort und Sprachen.','Unterhalten Sie sich über einen typischen Tag und Ihre Freizeit.','Vereinbaren Sie gemeinsam eine Aktivität: Termin, Ort und Aufgaben.'],
 'Telc-B1':['Lernen Sie Ihren Partner kennen. Fragen Sie nach Wohnort, Beruf, Familie, Sprachen und Hobbys.','A lernt lieber allein, weil Ruhe wichtig ist. B lernt lieber in einer Gruppe, weil Fragen geklärt werden. Berichten Sie über Ihren Text und tauschen Sie Meinungen und Erfahrungen aus.','Planen Sie gemeinsam einen Ausflug für Ihren Deutschkurs: Ziel, Termin, Fahrt, Essen und Kosten.'],
 'Telc-B2':['Berichten Sie über ein Buch, eine Reise, ein Erlebnis oder eine wichtige Person. Reagieren Sie auf Rückfragen Ihres Partners.','Diskutieren Sie Vor-/Nachteile von Homeoffice. Reagieren Sie auf die Argumente Ihres Partners und begründen Sie Ihre Position.','Organisieren Sie gemeinsam eine Veranstaltung für den Deutschkurs. Berücksichtigen Sie Programm, Ort, Aufgaben und Budget.'],
 'ÖSD-A1':['Stellen Sie sich kurz vor: Name, Herkunft, Wohnort, Sprachen und Beruf.','Beschreiben Sie eine Alltagssituation auf einem selbst gewählten Foto. Importieren oder ergänzen Sie ein Bild für diese Aufgabe.','Spielen Sie ein Gespräch im Geschäft: Sie möchten Obst kaufen und fragen nach Menge und Preis.'],
 'ÖSD-A2':['Stellen Sie sich anhand von Familie, Wohnen, Beruf, Freizeit und Sprachen vor. Stellen Sie Rückfragen.','Planen Sie gemeinsam einen freien Nachmittag: Ort, Zeit, Aktivität und Anreise.'],
 'ÖSD-B2':['Sie lernen eine Person auf einer Reise kennen. Sprechen Sie über Reiseziele und beraten Sie sie bei der Planung eines Aufenthalts.','Wählen Sie ein Foto aus und beschreiben und interpretieren Sie es. Importieren oder ergänzen Sie ein Foto und begründen Sie Ihre Auswahl.','Tauschen Sie Meinungen über das Lernen im Internet aus. Vertreten Sie Ihren Standpunkt mit Argumenten und reagieren Sie auf Einwände.']};
 const id=profile.exam==='ÖSD'&&profile.level==='B1'?'Goethe-B1':profile.exam+'-'+profile.level;return titles[id]?.[part.teil-1]||part.name;
}
function examPracticeBank(profile){return profile.modules.flatMap(module=>module.parts.map(part=>{const base={id:`format-${profile.exam}-${profile.level}-${module.key}-${part.teil}`,exam:profile.exam,level:profile.level,skill:module.key,teil:part.teil,title:part.name,authored:true,replays:part.replays};if(module.key==='writing'){const source=EXAMS[profile.exam+'-'+profile.level].parts.find(p=>p.teil===part.teil);let task={...source,...base,questions:[]};if(task.kind==='form'){if(profile.exam==='ÖSD'&&profile.level==='A1'){task.content='Ihr Freund Minh Tran wurde am 14. April 1998 geboren. Er plant im Juni einen Urlaub in Österreich. Er möchte ein Doppelzimmer mit Frühstück, reist mit dem Zug, möchte schwimmen und wandern und bezahlt mit Kreditkarte. Füllen Sie das Formular aus.';task.fields=[['Vorname','Minh'],['Nachname','Tran'],['Geburtsdatum','14.04.1998'],['Urlaubsland','Österreich'],['Monat','Juni'],['Zimmer','Doppelzimmer'],['Frühstück','Ja'],['Anreise','Zug'],['Sportarten','schwimmen und wandern'],['Bezahlung','Kreditkarte']].map(([label,answer])=>({label,answer}));}task.questions=(task.fields||[]).map((f,i)=>({id:'f'+i,prompt:f.label,answer:f.answer,answerSource:'authored'}));}return task;}if(module.key==='speaking')return {...base,content:speakingPractice(profile,part),questions:[],requiresImage:profile.exam==='ÖSD'&&['A1','B2'].includes(profile.level)&&part.teil===2};return {...base,...practiceQuestions(profile,module,part)};}));}
